SELECT

FROM Currencies a WHERE 1 = 1

    AND a.currency = #{currency}


    AND a.currencyName = #{currencyName}


    AND a.blockchain = #{blockchain}


    AND a.canDep = #{canDep}


    AND a.canWd = #{canWd}


    AND a.canInternal = #{canInternal}


    AND a.minWd = #{minWd}


    AND a.maxWd = #{maxWd}


    AND a.wdTickSz = #{wdTickSz}


    AND a.wdQuota = #{wdQuota}


    AND a.usedWdQuota = #{usedWdQuota}


    AND a.minFee = #{minFee}


    AND a.maxFee = #{maxFee}


    AND a.mainNet = #{mainNet}


    AND a.state = #{state}


    AND a.remark = #{remark}


    AND a.createTime = #{createTime}


    AND a.updateBy = #{updateBy}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM Currencies a WHERE 1 = 1

    AND a.currency LIKE CONCAT('%',#{currency}, '%')


    AND a.currencyName LIKE CONCAT('%',#{currencyName}, '%')


    AND a.blockchain LIKE CONCAT('%',#{blockchain}, '%')


    AND a.canDep LIKE CONCAT('%',#{canDep}, '%')


    AND a.canWd LIKE CONCAT('%',#{canWd}, '%')


    AND a.canInternal LIKE CONCAT('%',#{canInternal}, '%')


    AND a.minWd = #{minWd}


    AND a.maxWd = #{maxWd}


    AND a.wdTickSz = #{wdTickSz}


    AND a.wdQuota = #{wdQuota}


    AND a.usedWdQuota = #{usedWdQuota}


    AND a.minFee = #{minFee}


    AND a.maxFee = #{maxFee}


    AND a.mainNet LIKE CONCAT('%',#{mainNet}, '%')


    AND a.state LIKE CONCAT('%',#{state}, '%')


    AND a.remark LIKE CONCAT('%',#{remark}, '%')


    AND a.createTime = #{createTime}


    AND a.updateBy LIKE CONCAT('%',#{updateBy}, '%')


    AND a.updateTime = #{updateTime}
